SINA_SMART["anat1-thorax-osteology"] = {"lecture":"anat1-thorax-osteology","title":"Thorax part 2: osteology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-thorax-osteology:e0","text":"Thoracic cage: 12 vertebrae, 12 pairs of ribs, sternum + costal cartilages.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e1","text":"Sternum: manubrium, body, xiphoid (T9).","topic":"Sternum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e2","text":"Sternal angle: rib 2, T4-T5, aortic arch start/end, tracheal bifurcation.","topic":"Sternum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e3","text":"Sternoclavicular joint: only bony link of upper limb to axial skeleton.","topic":"Sternum","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e4","text":"True ribs 1-7; false 8-10; floating 11-12.","topic":"Ribs","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e5","text":"Typical rib: head, neck, tubercle, shaft with costal groove.","topic":"Ribs","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e6","text":"Fractures just anterior to the angle → pneumothorax risk.","topic":"Ribs","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e7","text":"Rib 1: scalene tubercle; subclavian vein in front, artery behind.","topic":"Ribs","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:e8","text":"Costal groove: vein, artery, nerve (VAN) from top to bottom.","topic":"Ribs","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-osteology:s3","text":"Describe and explain: Vertebral column","topic":"Vertebral column","sec":3,"importance":"standard","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1q4upq7":"a","yggwlm":"a","4tykdd":"a","wrur94":"a","cn1wqj":"a","12o8563":"a","rr3nab":"a","v04qag":"a","17h9jxb":"a","1u1qax":"a","15q2i5b":"a","xntlhg":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-thorax-osteology:e0":{"s":0,"u":["Thoracic cage: 12 vertebrae, 12 pairs of ribs, sternum + costal cartilages.","The thoracic skeleton is the 12 thoracic vertebrae behind, the 12 pairs of ribs at the sides and the sternum with the costal cartilages in front."],"dp":[]},"anat1-thorax-osteology:e1":{"s":1,"u":["Sternum: manubrium, body, xiphoid (T9).","Body : articulates with costal cartilages 2-7 (demifacet for 2, facets for 3-6, demifacet for 7)."],"dp":[]},"anat1-thorax-osteology:e2":{"s":1,"u":["Sternal angle: rib 2, T4-T5, aortic arch start/end, tracheal bifurcation.","Sternal angle (of Louis) : manubriosternal junction, a palpable ridge marking rib 2 (so all ribs can be counted), the T4-T5 level, the start and end of the aortic arch and the tracheal bifurcation ."],"dp":[]},"anat1-thorax-osteology:e3":{"s":1,"u":["Sternoclavicular joint: only bony link of upper limb to axial skeleton.","Manubrium : jugular notch flanked by the sternoclavicular joints (the only bony link between upper limb and axial skeleton); receives rib 1."],"dp":[]},"anat1-thorax-osteology:e4":{"s":2,"u":["True ribs 1-7; false 8-10; floating 11-12.","True ribs 1-7 attach directly to the sternum through their own cartilages; false ribs 8-10 join the cartilage above; floating ribs 11-12 have no anterior attachment.","Ribs run obliquely downward from back to front (rib 2 meets T2 behind but the sternal angle at T4 in front), so an axial CT slice cuts several ribs."],"dp":[{"h":"Note","t":"True ribs 1-7 (own cartilage to sternum); false 8-10 (join the cartilage above); floating 11-12 ."},{"h":"Note","t":"Ribs slope down and forward : rib 2 meets T2 posteriorly but the sternal angle is level with T4/T5, so one axial CT slice cuts several ribs."}]},"anat1-thorax-osteology:e5":{"s":2,"u":["Typical rib: head, neck, tubercle, shaft with costal groove.","Typical ribs (2-10) : head and neck (costovertebral joint with demifacets of adjacent vertebrae), tubercle (transverse process), shaft with a sharp lower border and the costal groove ; the anterior end joins the costal cartilage.","Atypical ribs 1, 11, 12 : rib 1 lies under the clavicle (not palpable) and bears the scalene tubercle (anterior scalene) with the groove for the subclavian vein in front and the subclavian artery behind ."],"dp":[]},"anat1-thorax-osteology:e6":{"s":2,"u":["Fractures just anterior to the angle → pneumothorax risk.","Fractures occur just anterior to the angle , the weakest point, and can tear the pleura ( pneumothorax )."],"dp":[{"h":"Clinical","t":"Rib fractures occur just anterior to the angle (weakest point) and may tear the pleura → pneumothorax . Lower rib fractures can injure the liver or spleen."}]},"anat1-thorax-osteology:e7":{"s":2,"u":["Rib 1: scalene tubercle; subclavian vein in front, artery behind.","Atypical ribs 1, 11, 12 : rib 1 lies under the clavicle (not palpable) and bears the scalene tubercle (anterior scalene) with the groove for the subclavian vein in front and the subclavian artery behind .","Ribs run obliquely downward from back to front (rib 2 meets T2 behind but the sternal angle at T4 in front), so an axial CT slice cuts several ribs."],"dp":[{"h":"Note","t":"Rib 1 : scalene tubercle (anterior scalene); subclavian vein in front , subclavian artery behind it. Xiphoid at T9."}]},"anat1-thorax-osteology:e8":{"s":2,"u":["Costal groove: vein, artery, nerve (VAN) from top to bottom.","In the costal groove, between the inner two layers: vein (highest), artery, nerve (lowest) : 'VAN'.","Atypical ribs 1, 11, 12 : rib 1 lies under the clavicle (not palpable) and bears the scalene tubercle (anterior scalene) with the groove for the subclavian vein in front and the subclavian artery behind ."],"dp":[{"h":"Why chest drains go above a rib","t":"The main intercostal vein, artery and nerve run in the groove under the lower border of each rib. Inserting a drain or needle just above the upper border of the rib below keeps it away from that main bundle, avoiding bleeding and nerve injury; only small collateral branches lie there. Source: the lecture's intercostal space section."},{"h":"Note","t":"VAN in the costal groove, top to bottom: Vein, Artery, Nerve ; the nerve is the least protected."}]},"anat1-thorax-osteology:s3":{"s":3,"u":["7 cervical, 12 thoracic , 5 lumbar vertebrae, the sacrum (5 fused) and the coccyx (3-4 fused).","Thoracic vertebrae carry costal facets on their bodies and transverse processes for the ribs."],"dp":[]}},"meta":{"1q4upq7":{"a":"recall","vg":"anat1-thorax-osteology:e1/recall/1"},"yggwlm":{"a":"recall","vg":"anat1-thorax-osteology:e0/recall/1"},"4tykdd":{"a":"relationship","vg":"anat1-thorax-osteology:e3/relationship/1"},"wrur94":{"a":"recall","vg":"anat1-thorax-osteology:e2/recall/1"},"cn1wqj":{"a":"recall","vg":"anat1-thorax-osteology:e4/recall/1"},"12o8563":{"a":"recall","vg":"anat1-thorax-osteology:e4/recall/2"},"rr3nab":{"a":"recall","vg":"anat1-thorax-osteology:e5/recall/1"},"v04qag":{"a":"recall","vg":"anat1-thorax-osteology:e6/recall/1"},"17h9jxb":{"a":"recall","vg":"anat1-thorax-osteology:e7/recall/1"},"1u1qax":{"a":"relationship","vg":"anat1-thorax-osteology:e8/relationship/1"},"15q2i5b":{"a":"recall","vg":"anat1-thorax-osteology:e3/recall/1"},"xntlhg":{"a":"recall","vg":"anat1-thorax-osteology:e0/recall/2"}},"explRev":"6d2d61a2576c"};
